         return
      end if
      do blk = 1, nblk
         call lpb_complex_tangent_one(state, dr(:, :, blk), dn(:, :, blk), dk1(:, blk), &
                                      dk2(:, blk), dxi(:, blk), dF(:, blk), da(:, blk), &
