                        tmp32793 = tmp32792*state%xi(i)
                        tmp32794 = tmp32793*tmp32728
                        tmp32795 = tmp32791 + tmp32794
                        tmp32796 = tmp32734*tmp32795
                        tmp32797 = 1.1283791670955126_wp*tmp32796
                        tmp32798 = tmp32734*tmp32790
                        tmp32799 = tmp32726**(2)
                        tmp32800 = tmp32485*tmp32799
                        tmp32801 = tmp32800*tmp32475
                        tmp32802 = tmp32801*tmp32734
                        tmp32803 = tmp32802*tmp32795
                        tmp32804 = tmp32803*tmp32401
                        tmp32805 = (-2.0_wp)*tmp32804
                        tmp32806 = tmp32798 + tmp32805
                        tmp32807 = tmp32806*tmp32401
                        tmp32808 = tmp32794*tmp32734
                        tmp32809 = tmp32807 + tmp32808
                        tmp32810 = (-1.1283791670955126_wp)*tmp32809
                        tmp32811 = tmp32797 + tmp32810
                        tmp32812 = tmp32775*tmp32811
                        tmp32490 = tmp32774 + tmp32812
                     end if
                     tmp32813 = state%cx_s27(i)*tmp32490
