      end block
      !$omp end parallel
      call gemv(state%s14, real(tmp4322, wp), tmp32815, trans="t")
      call gemv(state%s14, aimag(tmp4322), tmp32816, trans="t")
      tmp32814 = cmplx(tmp32815, tmp32816, wp)
      tmp32817 = tmp32396 + tmp32814
      tmp32818 = tmp32817 + tmp25518
      tmp32819 = tmp32818*state%cx_v
      tmp32820 = state%cx_s31*dv
      tmp32821 = tmp32819 + tmp32820
      tmp32822 = tmp13275*state%cx_s34
      tmp32823 = state%cx_s38*tmp13282
      tmp32824 = tmp32822 + tmp32823
      tmp32825 = tmp25518*state%cx_s32
      tmp32826 = state%cx_s30*tmp13289
      tmp32827 = tmp32825 + tmp32826
      tmp32828 = tmp32824 + tmp32827
      hvp_a = tmp32821 + tmp32828
      tmp32829 = 0.5_wp*tmp12091
      tmp32830 = tmp32829 + tmp4321
      tmp32831 = tmp32830 + tmp13294
      tmp32832 = tmp32818*state%a
      tmp32833 = state%cx_s31*da
      tmp32834 = tmp32832 + tmp32833
      hvp_v = tmp32831 + tmp32834
   end subroutine lpb_complex_tangent_one

   !> Linearized Poisson-Boltzmann (gaussian charges): linear response of the v gradient
   !>
   !> - Directions of v only; the state is not changed
   !> - Needs lpb_complex_solve on the same state first; keeps the state as it is
   !> - Arrays carry a last dimension nblk: one direction per column block
   !> - Vectors are (npt, nblk), point fields (3, npt, nblk)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
   !> @param[out] error  error handling; allocated on failure
   subroutine lpb_complex_response(state, dv, hvp_v, error)
      !> State of lpb
      type(lpb_complex_state), intent(inout) :: state
      !> Direction for v
      complex(wp), contiguous, intent(in) :: dv(:, :)
      !> Hessian times direction, v block
      complex(wp), contiguous, intent(out) :: hvp_v(:, :)
      !> Error handling
      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%matrix_free) then
         call lpb_complex_mf_response(state, dv, hvp_v, error)
         return
      end if
      if (state%cx_ready < 3 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[lpb_complex_response] call lpb_complex_solve first")
         return
      end if
      npt = state%npt
      nblk = size(dv, 2)
      if (any(shape(dv) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_complex_response] dv: wrong shape")
         return
      end if
      if (any(shape(hvp_v) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_complex_response] hvp_v: wrong shape")
         return
      end if
      do blk = 1, nblk
         call lpb_complex_response_one(state, dv(:, blk), hvp_v(:, blk), error)
         if (allocated(error)) return
      end do
   end subroutine lpb_complex_response

   !> One direction of lpb_complex_response
   !>
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
   !>
   !> @param[in,out] state  state of lpb
   !> @param[in] dv  direction for v
   !> @param[out] hvp_v  hessian times direction, v block
