      call gemv(state%cx_s13, aimag(tmp13), tmp16)
      tmp14 = cmplx(tmp15, tmp16, wp)
      tmp17 = state%cx_s2*tmp14
      tmp18 = tmp7 + tmp17
      tmp19 = 0.0_wp
