      if (allocated(error)) return
      tmp20 = 0.5_wp*tmp19
      tmp21 = 0.0_wp
      call state%solver%solve_complex(state%op5, .true., dv, tmp21, error)
      if (allocated(error)) return
      tmp22 = state%cx_s21*tmp21
      call gemv(state%cx_s13, real(tmp22, wp), tmp24, trans="t")
      call gemv(state%cx_s13, aimag(tmp22), tmp25, trans="t")
      tmp23 = cmplx(tmp24, tmp25, wp)
