      type(error_type), allocatable, intent(out) :: error

      integer :: npt, nblk, blk

      if (state%cx_ready < 4 .or. state%cx_assembled /= state%assembled) then
         call fatal_error(error, "[lpb_complex_mf_tangent] call lpb_complex_weights first")
         return
      end if
      npt = state%npt
      nblk = size(dr, 3)
      if (any(shape(dr) /= [3, npt, nblk])) then
         call fatal_error(error, "[lpb_complex_mf_tangent] dr: wrong shape")
         return
      end if
      if (any(shape(dn) /= [3, npt, nblk])) then
         call fatal_error(error, "[lpb_complex_mf_tangent] dn: wrong shape")
         return
      end if
      if (any(shape(dk1) /= [npt, nblk])) then
         call fatal_error(error, "[lpb_complex_mf_tangent] dk1: wrong shape")
         return
      end if
